import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.DuJmp0Ai.js";const u=JSON.parse('{"title":"Class: AABBUtils","description":"","frontmatter":{},"headers":[],"relativePath":"preview/math@beta/classes/AABBUtils.md","filePath":"preview/math@beta/classes/AABBUtils.md"}'),s={name:"preview/math@beta/classes/AABBUtils.md"};function n(i,e,h,l,d,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<p><a href="./../globals.html">@minecraft/math</a> / AABBUtils</p><h1 id="class-aabbutils" tabindex="-1">Class: AABBUtils <a class="header-anchor" href="#class-aabbutils" aria-label="Permalink to &quot;Class: AABBUtils&quot;">​</a></h1><p>Utilities operating on AABB objects. All methods are static and do not modify the input objects.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="epsilon" tabindex="-1">EPSILON <a class="header-anchor" href="#epsilon" aria-label="Permalink to &quot;EPSILON&quot;">​</a></h3><blockquote><p><code>static</code> <strong>EPSILON</strong>: <code>number</code></p></blockquote><p>EPSILON</p><p>The internal epsilon value that determines validity and used for block volume tolerance.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="createfromcornerpoints" tabindex="-1">createFromCornerPoints() <a class="header-anchor" href="#createfromcornerpoints" aria-label="Permalink to &quot;createFromCornerPoints()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>createFromCornerPoints</strong>(<code>pointA</code>, <code>pointB</code>): <code>AABB</code></p></blockquote><p>createFromCornerPoints</p><p>Gets an AABB from points defining it&#39;s corners, the order doesn&#39;t matter.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>pointA</strong>: <code>Vector3</code></p><p>The first corner point.</p><p>• <strong>pointB</strong>: <code>Vector3</code></p><p>The second corner point.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>AABB</code></p><ul><li>The resulting AABB.</li></ul><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if the resulting AABB is invalid. * *</p><hr><h3 id="dilate" tabindex="-1">dilate() <a class="header-anchor" href="#dilate" aria-label="Permalink to &quot;dilate()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>dilate</strong>(<code>aabb</code>, <code>size</code>): <code>AABB</code></p></blockquote><p>dilate</p><p>Creates a dilated AABB given a source AABB and dilation vector.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The source AABB.</p><p>• <strong>size</strong>: <code>Vector3</code></p><p>The dilation vector to add to the AABBs extent.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>AABB</code></p><ul><li>The resulting dilated AABB.</li></ul><h4 id="throws-1" tabindex="-1">Throws <a class="header-anchor" href="#throws-1" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if the input AABB is invalid. * *</p><hr><h3 id="equals" tabindex="-1">equals() <a class="header-anchor" href="#equals" aria-label="Permalink to &quot;equals()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>equals</strong>(<code>aabb</code>, <code>other</code>): <code>boolean</code></p></blockquote><p>equals</p><p>Compares the equality of two AABBs.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The first AABB in the comparison.</p><p>• <strong>other</strong>: <code>AABB</code></p><p>The second AABB in the comparison.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>boolean</code></p><ul><li>True if the center and extent of both AABBs are equal.</li></ul><h4 id="throws-2" tabindex="-1">Throws <a class="header-anchor" href="#throws-2" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if either of the input AABBs are invalid. * *</p><hr><h3 id="expand" tabindex="-1">expand() <a class="header-anchor" href="#expand" aria-label="Permalink to &quot;expand()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>expand</strong>(<code>aabb</code>, <code>other</code>): <code>AABB</code></p></blockquote><p>expand</p><p>Creates an expanded AABB given two source AABBs.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The first source AABB.</p><p>• <strong>other</strong>: <code>AABB</code></p><p>The second source AABB.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>AABB</code></p><ul><li>The resulting expanded AABB.</li></ul><h4 id="throws-3" tabindex="-1">Throws <a class="header-anchor" href="#throws-3" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if either of the input AABBs are invalid. * *</p><hr><h3 id="getblockvolume" tabindex="-1">getBlockVolume() <a class="header-anchor" href="#getblockvolume" aria-label="Permalink to &quot;getBlockVolume()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>getBlockVolume</strong>(<code>aabb</code>): <code>BlockVolume</code></p></blockquote><p>getBlockVolume</p><p>Creates the smallest BlockVolume that includes all of a source AABB.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The source AABB.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>BlockVolume</code></p><ul><li>The BlockVolume containing the source AABB.</li></ul><h4 id="throws-4" tabindex="-1">Throws <a class="header-anchor" href="#throws-4" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if the input AABB is invalid. * *</p><hr><h3 id="getintersection" tabindex="-1">getIntersection() <a class="header-anchor" href="#getintersection" aria-label="Permalink to &quot;getIntersection()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>getIntersection</strong>(<code>aabb</code>, <code>other</code>): <code>AABB</code></p></blockquote><p>getIntersection</p><p>Creates an AABB of the intersecting area of two source AABBs.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The first source AABB.</p><p>• <strong>other</strong>: <code>AABB</code></p><p>The second source AABB.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>AABB</code></p><ul><li>The resulting intersecting AABB if they intersect, otherwise returns undefined.</li></ul><h4 id="throws-5" tabindex="-1">Throws <a class="header-anchor" href="#throws-5" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if either of the input AABBs are invalid. * *</p><hr><h3 id="getmax" tabindex="-1">getMax() <a class="header-anchor" href="#getmax" aria-label="Permalink to &quot;getMax()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>getMax</strong>(<code>aabb</code>): <code>Vector3</code></p></blockquote><p>getMax</p><p>Gets the maximum corner of an AABB.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The AABB to retrieve the maximum corner of.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Vector3</code></p><ul><li>The maximum corner of the AABB.</li></ul><h4 id="throws-6" tabindex="-1">Throws <a class="header-anchor" href="#throws-6" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if the input AABB is invalid. * *</p><hr><h3 id="getmin" tabindex="-1">getMin() <a class="header-anchor" href="#getmin" aria-label="Permalink to &quot;getMin()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>getMin</strong>(<code>aabb</code>): <code>Vector3</code></p></blockquote><p>getMin</p><p>Gets the minimum corner of an AABB.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The AABB to retrieve the minimum corner of.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Vector3</code></p><ul><li>The minimum corner of the AABB.</li></ul><h4 id="throws-7" tabindex="-1">Throws <a class="header-anchor" href="#throws-7" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if the input AABB is invalid. * *</p><hr><h3 id="getspan" tabindex="-1">getSpan() <a class="header-anchor" href="#getspan" aria-label="Permalink to &quot;getSpan()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>getSpan</strong>(<code>aabb</code>): <code>Vector3</code></p></blockquote><p>getSpan</p><p>Gets the span of an AABB.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The AABB to retrieve the span of.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Vector3</code></p><ul><li>The span of the AABB.</li></ul><h4 id="throws-8" tabindex="-1">Throws <a class="header-anchor" href="#throws-8" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if the input AABB is invalid. * *</p><hr><h3 id="intersects" tabindex="-1">intersects() <a class="header-anchor" href="#intersects" aria-label="Permalink to &quot;intersects()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>intersects</strong>(<code>aabb</code>, <code>other</code>): <code>boolean</code></p></blockquote><p>intersects</p><p>Calculates if two AABBs are intersecting.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The first AABB.</p><p>• <strong>other</strong>: <code>AABB</code></p><p>The second AABB.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>boolean</code></p><ul><li>True if the AABBs are intersecting, otherwise false.</li></ul><h4 id="throws-9" tabindex="-1">Throws <a class="header-anchor" href="#throws-9" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if either of the input AABBs are invalid. * *</p><hr><h3 id="isinside" tabindex="-1">isInside() <a class="header-anchor" href="#isinside" aria-label="Permalink to &quot;isInside()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>isInside</strong>(<code>aabb</code>, <code>pos</code>): <code>boolean</code></p></blockquote><p>isInside</p><p>Calculates if a position is inside of an AABB.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The AABB to test against.</p><p>• <strong>pos</strong>: <code>Vector3</code></p><p>The position to test.</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>boolean</code></p><p>True if the position is inside of the AABB, otherwise returns false.</p><h4 id="throws-10" tabindex="-1">Throws <a class="header-anchor" href="#throws-10" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if the input AABB is invalid. * *</p><hr><h3 id="isvalid" tabindex="-1">isValid() <a class="header-anchor" href="#isvalid" aria-label="Permalink to &quot;isValid()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>isValid</strong>(<code>aabb</code>): <code>boolean</code></p></blockquote><p>isValid</p><p>Determines if the AABB has non-zero extent on all axes.</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The AABB to test for validity.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>boolean</code></p><ul><li>True if all extent axes are non-zero, otherwise false.</li></ul><hr><h3 id="throwerrorifinvalid" tabindex="-1">throwErrorIfInvalid() <a class="header-anchor" href="#throwerrorifinvalid" aria-label="Permalink to &quot;throwErrorIfInvalid()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>throwErrorIfInvalid</strong>(<code>aabb</code>): <code>void</code></p></blockquote><p>throwErrorIfInvalid</p><p>Throws an error if the AABB is invalid.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The AABB to test for validity.</p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><h4 id="throws-11" tabindex="-1">Throws <a class="header-anchor" href="#throws-11" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if the input AABB is invalid.</p><hr><h3 id="translate" tabindex="-1">translate() <a class="header-anchor" href="#translate" aria-label="Permalink to &quot;translate()&quot;">​</a></h3><p><span class="mod-badge">static</span></p><blockquote><p><strong>translate</strong>(<code>aabb</code>, <code>delta</code>): <code>AABB</code></p></blockquote><p>translate</p><p>Creates a translated AABB given a source AABB and translation vector.</p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><p>• <strong>aabb</strong>: <code>AABB</code></p><p>The source AABB.</p><p>• <strong>delta</strong>: <code>Vector3</code></p><p>The translation vector to add to the AABBs center.</p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>AABB</code></p><ul><li>The resulting translated AABB.</li></ul><h4 id="throws-12" tabindex="-1">Throws <a class="header-anchor" href="#throws-12" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p><a href="./AABBInvalidExtentError.html">AABBInvalidExtentError</a> * This exception is thrown if the input AABB is invalid. * *</p>',217)])])}const B=a(s,[["render",n]]);export{u as __pageData,B as default};
